query:
SELECT id, name, cas_number, formula, chemical_class, smiles IS NOT NULL as has_smiles,
  LENGTH(COALESCE(notes,'')) as notes_len,
  (SELECT COUNT(*) FROM plant_molecules pm WHERE pm.molecule_id = m.id) as plant_links
FROM molecules m
WHERE id IN (1710025, 1710027)
ORDER BY id;

SELECT COUNT(*) as total_molecules FROM molecules;
SELECT COUNT(*) as total_links FROM plant_molecules;

